export const NEONBLADE_KNOWLEDGE: string = "# NEONBLADE UI - COMPLETE COMPONENT REFERENCE\n\n## General Info\nNeonBlade UI is a free, open-source futuristic/cyberpunk React component library.\nInstall via CLI: npx neonblade add <component-slug>\nRegistry: https://neonbladeui-registry.vercel.app/components/<slug>/index.tsx\nTech: Next.js / React, Tailwind CSS v4, TypeScript, Framer Motion, Lucide React\nAccent colors: cyan=#00f3ff | pink=#ff00ff | green=#39ff14\nCSS vars: --neon-cyan, --neon-pink, --neon-green, --background (#050505)\nFonts: font-orbitron (headings), Rajdhani (body text)\nPackage manager: pnpm | Monorepo: Turborepo\n\n## Design Principles\n- Dark near-black background (#050505)\n- Neon glows via box-shadow/drop-shadow\n- Corner-cut geometry via clip-path polygon\n- Animations: mechanical and precise\n- Color props accept preset (\"cyan\"|\"pink\"|\"green\") or any CSS color string\n\n## Available Categories\n- Backgrounds\n- Cards\n- Elements\n- Progress\n- Text\n- Buttons\n- Navbars\n- Footers\n- Inputs\n- Sliders\n- Cursors\n- Tables\n- Charts\n\n---\n## Accent Frame\nSlug: accent-frame\nDescription: A dynamic frame with animated corner accents.\n\nUsage Example:\n```tsx\nimport AccentFrame from \"@/lib/components/ui/elements/AccentFrame\";\\n\\nexport default function App() {\\n  return (\\n    <div className=\"flex flex-col gap-8\">\\n      {/* Default: expand on hover, duo corners */}\\n      <AccentFrame color=\"cyan\" className=\"text-white text-center\">\\n        Hover to expand\\n      </AccentFrame>\\n\\n      {/* Quad corners + dual color + glow */}\\n      <AccentFrame\\n        color=\"cyan\"\\n        colorB=\"pink\"\\n        mode=\"quad\"\\n        hoverEffect=\"glow\"\\n        glowIntensity=\"high\"\\n        className=\"text-whit\n```\n\nProps:\n  color: \"cyan\" | \"pink\" | \"green\" | string - Primary corner accent color. Preset name or any CSS color.\n  colorB: \"cyan\" | \"pink\" | \"green\" | string - Secondary accent color for the opposite-diagonal bracket pair. Defaults to the primary color.\n  glowIntensity: \"low\" | \"medium\" | \"high\" - Controls the spread radius of glow/pulse effects.\n  animated [default: false] - When true the chosen hoverEffect runs continuously without requiring hover.\n  cornerStyle: \"square\" | \"rounded\" - Square or rounded bracket tip ends.\n  cornerLength [default: 16] - Base arm length of each bracket in px.\n  cornerThickness [default: 2] - Stroke thickness of the bracket in px.\n  transitionDuration [default: 300] - Expand / transition animation speed in ms.\n\n---\n## Arrow Loader\nSlug: arrow-loader\nDescription: Full-width indeterminate loader with flowing SVG chevron arrows. Fully customizable arrow size, gap, thickness, speed, and color.\n\nUsage Example:\n```tsx\nimport ArrowLoader from \"@/components/neonblade-ui/arrow-loader\";\r\n\r\n// Default cyan loader (8px tall)\r\nexport default function App() {\r\n  return <ArrowLoader color=\"cyan\" height={8} />;\r\n}\r\n\r\n// Dense fast arrows\r\nexport function FastDense() {\r\n  return <ArrowLoader color=\"pink\" height={12} arrowSize={6} gap={4} speed={200} />;\r\n}\r\n\r\n// Thick slow arrows\r\nexport function ThickSlow() {\r\n  return <ArrowLoader color=\"#ffb800\" height={12} arrowSize={18} gap={14} thickness={4} speed={1200} />;\r\n}\n```\n\nProps:\n  color: \"cyan\" | \"pink\" | \"green\" | string - Neon accent color for the arrows.\n  height [default: 8] - Bar height in pixels.\n  arrowSize [default: 10] - Pixel width of each individual › arrow shape.\n  gap [default: 8] - Pixel gap between arrows.\n  thickness [default: 2.5] - SVG stroke width — controls arrow line thickness.\n  speed [default: 450] - Animation cycle duration in ms. Lower = faster.\n  trackColor - Background color of the track strip behind the arrows. Accepts any valid CSS color.\n  className - Additional className on the wrapper element.\n\n---\n## Ascii Rain\nSlug: ascii-rain\nDescription: A futuristic falling ASCII matrix effect.\n\nUsage Example:\n```tsx\nimport { AsciiRain } from \"@/lib/components/ui/backgrounds/AsciiRain\";\\n\\nexport default function App() {\\n  return (\\n    <div className=\"relative w-screen h-screen\">\\n      <AsciiRain />\\n    </div>\\n  );\\n}\n```\n\nProps:\n  textColor - Color of the falling text.\n  bgColor - Background masking color for creating character trails.\n  fontSize [default: 14] - Width and font-size of the columns.\n  speed [default: 33] - Milliseconds between each rendering frame.\n  characters - A string slice representing possible characters.\n  opacity [default: 60] - Base visual opacity constraint scaling to 100.\n\n---\n## Badge\nSlug: badge\nDescription: Futuristic label badge with pill, rectangle, and corner-cut shapes, dot indicators, and glow.\n\nUsage Example:\n```tsx\nimport Badge from \"@/lib/components/ui/elements/Badge\";\\n\\nexport default function App() {\\n  return (\\n    <div className=\"flex flex-wrap gap-4 items-center\">\\n      {/* Default pill, outline, flicker dot */}\\n      <Badge color=\"cyan\" dot=\"flicker\">\\n        Live\\n      </Badge>\\n\\n      {/* Solid variant */}\\n      <Badge color=\"pink\" variant=\"solid\" size=\"md\">\\n        New\\n      </Badge>\\n\\n      {/* Ghost with pulse dot */}\\n      <Badge color=\"green\" variant=\"ghost\" dot=\"pulse\">\\n        Online\\n      </Badge>\\n\\n      {/* Corner-cut sha\n```\n\nProps:\n  children - Badge label — text or any inline React node.\n  color: \"cyan\" | \"pink\" | \"green\" | string - Accent color. Use a preset name or any CSS color value.\n  corner: \"bottom-right\" | \"bottom-left\" | \"top-right\" | \"top-left\" | \"all\" - Which corner is cut. Only applies when shape is corner-cut.\n  cornerSize [default: 8] - Depth of the diagonal corner cut in pixels. Only applies when shape is corner-cut.\n  glow [default: false] - Adds a neon box-shadow and text-shadow glow using the badge color.\n  size: \"xs\" | \"sm\" | \"md\" - Controls badge padding and font size.\n\n---\n## Border Beam Corner Cut\nSlug: border-beam-corner-cut-card\nDescription: A corner cut card with a spinning border beam.\n\nUsage Example:\n```tsx\nimport BorderBeamCornerCutCard from \"@/lib/components/ui/cards/BorderBeamCornerCutCard\";\\nimport { Terminal, Zap } from \"lucide-react\";\\n\\nexport default function App() {\\n  return (\\n    <div className=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\\n      {/* Default single beam with icon/title/description */}\\n      <BorderBeamCornerCutCard\\n        beamColor=\"pink\"\\n        title=\"CLI Installation\"\\n        description=\"Install components directly into your project via CLI.\"\\n        icon={<Terminal className=\"w-full h-full\" />}\\n      />\\n\\n     \n```\n\nProps:\n  children - Free-form slot rendered below the optional title/description.\n  icon - Element rendered inside the top icon box (e.g. a Lucide icon).\n  title - Card heading text.\n  description - Body copy rendered below the title.\n  beamColor: \"cyan\" | \"pink\" | \"green\" | string - Primary beam color. Preset name or any CSS color.\n  duration [default: 4] - Primary beam rotation speed in seconds.\n  durationB [default: 6] - Secondary beam rotation speed in seconds (dual variant only).\n  borderWidth - Visible beam border width — becomes the padding between outer and inner card.\n  size: \"sm\" | \"md\" | \"lg\" | \"xl\" - Controls inner padding, icon box size and font sizes.\n  corner: \"bottom-right\" | \"bottom-left\" | \"top-right\" | \"top-left\" | \"all\" - Which corner(s) receive the diagonal cut.\n  cornerSize [default: 20] - Depth of the diagonal corner cut in pixels.\n  glowIntensity: \"none\" | \"low\" | \"medium\" | \"high\" - Ambient neon glow spread on the inner card surface.\n  bgColor - Override the inner card background color (default: var(--background)).\n  innerClassName - Extra className applied to the inner content div.\n\n---\n## Card Slider\nSlug: card-slider\nDescription: A generic card / image / video slider with touch swipe, arrow navigation, progress indicator (bar, dots, or counter), responsive visible count, auto-play, and full color customization.\n\nUsage Example:\n```tsx\nimport CardSlider from \"@/lib/components/ui/sliders/CardSlider\";\r\n\r\n// ── Basic usage: image/video slider ──────────────────────────────────────────\r\nexport function HeroSlider() {\r\n  return (\r\n    <CardSlider\r\n      visibleCount={1}          // one slide at a time\r\n      gap={0}                   // no gap (full-bleed)\r\n      accentColor=\"#00f3ff\"\r\n      progressStyle=\"bar\"       // \"bar\" | \"dots\" | \"counter\"\r\n      buttonPosition=\"sides\"    // \"sides\" (default) | \"bottom\"\r\n      loop                      // wrap around at ends\r\n    >\r\n      <\n```\n\nProps:\n  children [default: —] - Slides to render. Pass any ReactNode: <img>, <video>, custom cards, etc. Each child occupies one slide slot.\n  gap [default: 16] - Gap between slide items in pixels.\n  showButtons [default: true] - Show previous / next arrow navigation buttons.\n  buttonCornerSize [default: 10] - Size of the diagonal corner cut on navigation buttons in pixels.\n  prevButtonCorner: \"top-right\" | \"top-left\" | \"bottom-right\" | \"bottom-left\" - Which corner is cut on the previous (left) navigation button.\n  nextButtonCorner: \"top-right\" | \"top-left\" | \"bottom-right\" | \"bottom-left\" - Which corner is cut on the next (right) navigation button.\n  enableSwipe [default: true] - Enable touch-swipe and mouse-drag navigation.\n  swipeThreshold [default: 50] - Minimum drag distance in pixels required to trigger a slide change.\n  showProgress [default: true] - Show a progress indicator below the viewport.\n  loop [default: false] - Loop back to the first slide after the last one.\n  autoPlay [default: false] - Auto-advance slides at the interval set by autoPlayInterval. Pauses on hover.\n  autoPlayInterval [default: 3000] - Interval between auto-advance steps in milliseconds.\n  accentColor - Primary accent / neon glow color. Used for buttons, progress, corner accents, and all glow effects.\n  edgeFadeColor - Color for the gradient edge-fades. Set this to your page background color for a natural blend.\n  showEdgeFades [default: false] - Overlay gradient fades on the left and right edges of the viewport.\n  showCornerAccents [default: true] - Display corner accent decorations on each slide/card item.\n  scanLines [default: false] - Overlay subtle CRT horizontal scan-lines on the viewport for a retro cyberpunk effect.\n  className - Additional CSS classes applied to the root wrapper element.\n  viewportClassName - Additional CSS classes applied to the overflow-hidden viewport element.\n  itemClassName - Additional CSS classes applied to each slide item slot.\n\n---\n## Circular Progress\nSlug: circular-progress\nDescription: SVG arc-based radial progress ring with neon glow filter, animated fill transition, tick mark at origin, center value display, and sub-label. Zero dependencies beyond React.\n\nUsage Example:\n```tsx\nimport CircularProgress from \"@/components/neonblade-ui/circular-progress\";\n\n// Default (md, cyan)\nexport default function App() {\n  return <CircularProgress value={73} color=\"cyan\" size=\"md\" />;\n}\n\n// Large with sub-label and high glow\nexport function CPU() {\n  return (\n    <CircularProgress\n      value={73}\n      color=\"cyan\"\n      size=\"lg\"\n      subLabel=\"CPU\"\n      glowIntensity=\"high\"\n    />\n  );\n}\n\n// Custom center label\nexport function Custom() {\n  return <CircularProgress value={58} centerLabel=\"58%\" subLabel=\"MEM\" color=\"pink\" size=\"l\n```\n\nProps:\n  value - Current fill value (0 to max).\n  max [default: 100] - Maximum value.\n  color: \"cyan\" | \"pink\" | \"green\" | string - Neon accent color for the arc stroke.\n  size: \"sm\" | \"md\" | \"lg\" | \"xl\" - Overall diameter preset.\n  strokeWidth - Arc stroke width in px. Auto-derived from size if omitted.\n  showValue [default: true] - Show the percentage value in the center.\n  centerLabel - Custom center label (replaces the auto %).\n  subLabel - Smaller sub-label below the value.\n  glowIntensity: \"none\" | \"low\" | \"medium\" | \"high\" - Neon drop-shadow glow on the arc.\n  className - Additional className on the wrapper.\n\n---\n## Corner Cut Button\nSlug: corner-cut-button\nDescription: A button with a diagonal corner cut, multiple variants, colors, sizes and hover effects.\n\nUsage Example:\n```tsx\nimport CornerCutButton from \"@/lib/components/ui/buttons/CornerCutButton\";\\n\\nexport default function App() {\\n  return (\\n    <div className=\"flex gap-4 flex-wrap\">\\n      {/* Solid — matches the Hero \"Explore Components\" button */}\\n      <CornerCutButton color=\"cyan\" showArrow hoverEffect=\"glow\">\\n        Explore Components\\n      </CornerCutButton>\\n\\n      {/* Outline variant */}\\n      <CornerCutButton color=\"pink\" variant=\"outline\" hoverEffect=\"shift\">\\n        View Docs\\n      </CornerCutButton>\\n\\n      {/* Ghost with pulse glow */}\\n \n```\n\nProps:\n  children - Button label content.\n  size: \"xs\" | \"sm\" | \"md\" | \"lg\" | \"xl\" - Controls padding and font size.\n  variant: \"solid\" | \"outline\" | \"ghost\" - Visual style. solid fills with the accent color (matches the Hero button), outline adds a border, ghost is subtly tinted.\n  corner: \"bottom-right\" | \"bottom-left\" | \"top-right\" | \"top-left\" | \"all\" - Which corner(s) receive the diagonal cut.\n  cornerSize [default: 20] - Depth of the corner diagonal cut in pixels.\n  hoverEffect: \"glow\" | \"shift\" | \"shine\" | \"pulse\" | \"scan\" | \"flicker\" | \"none\" - Hover animation preset applied to the button.\n  hoverColor: \"cyan\" | \"pink\" | \"green\" | string [default: —] - Override the color used for hover glow/pulse/shift effects. Falls back to `color` when not set. Accepts any CSS color string or preset name.\n  hoverOutline [default: false] - Hover outline effect. Only applies when variant='solid' and hoverEffect='shift'. When true the button transitions to an outline style on hover.\n  glowIntensity: \"low\" | \"medium\" | \"high\" - Spread radius of neon glow effects.\n  showArrow [default: false] - Appends a → arrow that slides right on hover.\n\n---\n## Crosshair\nSlug: crosshair\nDescription: Animated crosshair cursor with two counter-rotating partial rings and a center crosshair. Fully customizable colors, sizes, ring thickness, arc gap, speed, and glow.\n\nUsage Example:\n```tsx\nimport { Crosshair } from \"@/lib/components/ui/cursors/Crosshair\";\r\n\r\nexport default function App() {\r\n  return (\r\n    <>\r\n      {/* Drop anywhere — fixed positioning handles the rest */}\r\n      <Crosshair color=\"cyan\" />\r\n\r\n      {/* Pink with larger rings */}\r\n      <Crosshair\r\n        color=\"pink\"\r\n        outerSize={56}\r\n        innerSize={34}\r\n        outerThickness={2.5}\r\n        innerThickness={1.5}\r\n        glowIntensity=\"high\"\r\n      />\r\n\r\n      {/* Green, faster spin, narrow arc gap */}\r\n      <Crosshair\r\n        color=\"green\"\r\n      \n```\n\nProps:\n  outerSize [default: 44] - Outer ring diameter in pixels.\n  innerSize [default: 26] - Inner ring diameter in pixels.\n  outerThickness [default: 2] - Outer ring stroke thickness in pixels.\n  innerThickness [default: 1.5] - Inner ring stroke thickness in pixels.\n  arcGap [default: 0.3] - Fraction of each ring that is invisible (the gap). 0 = full circle, 0.3 = 70% arc, 0.5 = semicircle.\n  outerSpeed [default: 3] - Outer ring rotation period in seconds per full revolution. Smaller = faster.\n  innerSpeed [default: 2] - Inner ring rotation period in seconds per full revolution. Smaller = faster.\n  crosshairSize [default: 7] - Length of each crosshair arm in pixels.\n  crosshairGap [default: 3] - Gap between the crosshair center and the start of each arm in pixels.\n  crosshairThickness [default: 1] - Crosshair line stroke thickness in pixels.\n  glowIntensity: \"none\" | \"low\" | \"medium\" | \"high\" - Neon glow intensity (drop-shadow) around the rings and crosshair.\n  hideNativeCursor [default: true] - When true, hides the native OS cursor while the component is mounted (sets body cursor: none).\n  disabled [default: false] - Completely disables the custom cursor and renders nothing.\n\n---\n## Cyber Circuit\nSlug: cyber-circuit\nDescription: Static SVG circuit traces entering from the corners with glowing terminal nodes. Configurable colors, line weight, dot style, and glow intensity.\n\nUsage Example:\n```tsx\nimport { CyberCircuit } from \"@/lib/components/ui/backgrounds/CyberCircuit\";\r\n\r\nexport default function MyPage() {\r\n  return (\r\n    <div className=\"relative w-full h-[320px] sm:h-[500px] bg-slate-950 flex items-center justify-center overflow-hidden\">\r\n      {/* Circuit Background */}\r\n      <CyberCircuit\r\n        className=\"z-0\"\r\n        color=\"#00f3ff\"\r\n        opacity={0.65}\r\n        lineThickness={2}\r\n        dotSize={3}\r\n        dotType=\"filled\" // \"filled\" | \"outline\"\r\n        glowColor=\"#00f3ff\"\r\n        glowIntensity=\"medium\" // \"none\" |\n```\n\nProps:\n  className [default: undefined] - Additional CSS classes to apply to the container.\n  color [default: #00f3ff] - The CSS color string for the circuit traces and nodes.\n  opacity [default: 0.6] - The opacity of the circuit background (0.0 to 1.0).\n  lineThickness [default: 2] - Base thickness of the circuit traces.\n  dotSize [default: 3] - Base radius used for terminal node circles.\n  dotType: \"filled\" | \"outline\" - Node style variant for circuit endpoints.\n  glowColor [default: #00f3ff] - Glow color applied to lines and terminal nodes.\n\n---\n## Datalines With Grid\nSlug: datalines-with-grid\nDescription: A grid with random data line tracers.\n\nUsage Example:\n```tsx\nimport { DatalinesWithGrid } from \"@/lib/components/ui/backgrounds/DatalinesWithGrid\";\\n\\nexport default function App() {\\n  return (\\n    <div className=\"relative w-screen h-screen\">\\n      <DatalinesWithGrid />\\n    </div>\\n  );\\n}\n```\n\nProps:\n  lineColor - The color for the line tracers.\n  shadowColor - The hex color for the trail shadow.\n  bgGridColor - Color for the grid cells border.\n  cellSize [default: 50] - Size of the simulated grid tiles.\n  maxLines [default: 15] - Maximum number of simultaneous data lines.\n  baseSpeed [default: 2] - Flow speed multiplier.\n  lineLength [default: 150] - Visual length of each data line in pixels. Stays constant regardless of baseSpeed.\n  spawnProbability [default: 0.1] - Chance per frame to spawn a new line.\n  overlay [default: false] - Whether to overlay the grid on top of existing content.\n\n---\n## Footer\nSlug: footer\nDescription: Fully customizable footer: minimal, columns, centered, and mega variants with link groups, social links, newsletter, and accent color system.\n\nUsage Example:\n```tsx\nimport Footer, {\\n  GithubIcon,\\n  TwitterIcon,\\n  DiscordIcon,\\n  LinkedInIcon,\\n} from \"@/lib/components/ui/footers/Footer\";\\n\\nconst socialLinks = [\\n  { label: \"GitHub\",   href: \"https://github.com\",   icon: <GithubIcon /> },\\n  { label: \"Twitter\",  href: \"https://twitter.com\",  icon: <TwitterIcon /> },\\n  { label: \"Discord\",  href: \"https://discord.com\",  icon: <DiscordIcon /> },\\n  { label: \"LinkedIn\", href: \"https://linkedin.com\", icon: <LinkedInIcon /> },\\n];\\n\\nconst linkGroups = [\\n  {\\n    title: \"Product\",\\n    links: [\\n      { lab\n```\n\nProps:\n  color: \"cyan\" | \"pink\" | \"green\" | string - Accent color applied to link hovers, social icon borders, newsletter button, group titles, and the top border glow. Preset name or any CSS color.\n  logo - Logo: an image URL string (rendered as <img>) or any ReactNode (e.g. a custom SVG component).\n  logoText - Brand text displayed beside the logo.\n  logoHref - href the logo links to.\n  description - Short brand description shown below the logo. Used in columns and mega variants.\n  linkGroups [default: []] - Columns of links. Each group has a title and a links array. Used in columns and mega variants.\n  navLinks [default: []] - Flat navigation links. Shown inline in minimal and centered variants, and in the bottom bar of columns/mega.\n  socialLinks [default: []] - Social icon links. Each entry has label, href, and an icon ReactNode. Built-in icons: GithubIcon, TwitterIcon, DiscordIcon, LinkedInIcon.\n  showNewsletter [default: false] - Show an email newsletter subscription form. Available in the mega variant.\n  newsletterPlaceholder - Placeholder text for the newsletter email input.\n  newsletterButtonLabel - Label for the newsletter submit button.\n  onNewsletterSubmit - Callback fired when the newsletter form is submitted. Receives the trimmed email string.\n  topBorder [default: true] - Show a top accent-colored glow border line at the top of the footer.\n  className - Extra CSS class names applied to the <footer> element.\n\n---\n## Fox Cursor\nSlug: fox-cursor\nDescription: Geometric fox face cursor. Customizable color, size, stroke width, glow, and fill opacity.\n\nUsage Example:\n```tsx\nimport { FoxCursor } from \"@/lib/components/ui/cursors/FoxCursor\";\n\nexport default function App() {\n  return (\n    <>\n      {/* Drop anywhere — fixed positioning handles the rest */}\n      <FoxCursor color=\"cyan\" />\n\n      {/* Pink, larger, with subtle fill */}\n      <FoxCursor\n        color=\"pink\"\n        size={80}\n        strokeWidth={2.5}\n        glowIntensity=\"high\"\n        fillOpacity={0.4}\n      />\n\n      {/* Scoped to a container */}\n      <FoxCursor\n        color=\"green\"\n        size={56}\n        glowIntensity=\"low\"\n        containerRef\n```\n\nProps:\n  size [default: 64] - Overall pixel size of the fox face SVG (width and height).\n  strokeWidth [default: 2] - Stroke thickness of the fox face lines in SVG units.\n  glowIntensity: \"none\" | \"low\" | \"medium\" | \"high\" - Neon drop-shadow glow intensity around the fox face.\n  fillOpacity [default: 0] - Opacity of the translucent fill inside the face and nose shapes (0 = outline only, 1 = full fill).\n  hideNativeCursor [default: true] - When true, hides the native OS cursor while the component is mounted.\n  disabled [default: false] - Completely disables the custom cursor and renders nothing.\n  containerRef [default: undefined] - When provided, scopes the cursor to that element (absolute positioning, hides on mouse leave). The container must have position: relative and overflow: hidden.\n\n---\n## Glitch Text\nSlug: glitch-text\nDescription: Animated RGB split, CSS-only glitch effect.\n\nUsage Example:\n```tsx\nimport GlitchText from \"@/lib/components/ui/text/GlitchText\";\\n\\nexport default function App() {\\n  return (\\n    <div className=\"flex flex-col gap-8\">\\n      {/* children-only — text prop is inferred automatically */}\\n      <h2 className=\"text-4xl font-bold font-orbitron uppercase text-white\">\\n        <GlitchText mode=\"hover\">Hover Glitch</GlitchText>\\n      </h2>\\n\\n      {/* active + heavy + fast */}\\n      <h2 className=\"text-4xl font-bold font-orbitron uppercase text-white\">\\n        <GlitchText mode=\"active\" intensity=\"heavy\" speed=\"fas\n```\n\nProps:\n  text - String passed to data-text — must match the children text for the CSS pseudo-element channels to line up.\n  speed: \"slow\" | \"normal\" | \"fast\" | \"frenzy\" - Animation loop speed shorthand (2 s / 1 s / 0.45 s / 0.2 s).\n  colorA: \"cyan\" | \"pink\" | \"green\" | string - Color of the ::before channel text-shadow (preset or CSS color).\n  colorB: \"cyan\" | \"pink\" | \"green\" | string - Color of the ::after channel text-shadow (preset or CSS color).\n  offset [default: 2] - Horizontal split offset of the RGB channels in px.\n  neon [default: false] - Adds a neon text-shadow glow around the text.\n  neonFlicker [default: false] - When neon is true, also animates a neon-flicker on the glow.\n  glowColor: \"cyan\" | \"pink\" | \"green\" | string - Color of the neon glow (defaults to colorB).\n  glitchDuration - (Deprecated) Legacy loop duration in seconds. Use speed or customSpeed instead.\n\n---\n## Glyph City\nSlug: glyph-city\nDescription: Animated glyph cityscape with neon buildings, antennas, blinking peak lights, and flying vehicles.\n\nUsage Example:\n```tsx\nimport { GlyphCity } from \"@/lib/components/ui/backgrounds/GlyphCity\";\r\n\r\n// Solid mode\r\nexport function SolidCity() {\r\n  return (\r\n    <div className=\"relative w-screen h-screen\">\r\n      <GlyphCity\r\n        cityType=\"solid\"\r\n        variant=\"downtown\"\r\n        colorPrimary=\"#00ffff\"\r\n        colorSecondary=\"#ff00ff\"\r\n        colorTertiary=\"#ffff00\"\r\n        bgColor=\"#020208\"\r\n        fontSize={12}\r\n        speed={80}\r\n        showVehicles\r\n        blinkingLights\r\n        opacity={92}\r\n      />\r\n    </div>\r\n  );\r\n}\r\n\r\n// Outline silhouette mode\n```\n\nProps:\n  variant: \"downtown\" | \"megacity\" | \"district\" | \"ruins\" - City layout variant for solid mode. downtown = tall dense towers; megacity = wall-to-wall packed high-rises; district = lower varied buildings; ruins = short crumbling structures.\n  outlineVariant: \"sparse\" | \"dense\" | \"layered\" | \"horizon\" - City layout variant for outline mode. sparse = wide spaced tall towers; dense = tightly packed high-rises; layered = buildings with setbacks and terracing; horizon = wide low silhouette.\n  colorPrimary - Primary neon color used for most building structures and ground line.\n  colorSecondary - Secondary neon color used for accent buildings, windows, and flying vehicles.\n  colorTertiary - Tertiary color used for antennas, tower peak lights, and a third vehicle type.\n  bgColor - Canvas background fill color.\n  fontSize [default: 12] - Font size in px. Also controls column/row density — smaller values produce denser cities.\n  speed [default: 80] - Milliseconds between each animation frame. Lower = faster animation.\n  showVehicles [default: true] - Render flying vehicles with motion trails across the skyline.\n  blinkingLights [default: true] - Enable blinking peak lights on antenna towers.\n  opacity [default: 90] - Overall canvas opacity scaled to 100.\n  className [default: undefined] - Additional CSS class names forwarded to the wrapper div.\n\n---\n## Grid Floor\nSlug: grid-floor\nDescription: Canvas-based perspective synthwave grid with scrolling horizontal lines, neon glow, and configurable horizon.\n\nUsage Example:\n```tsx\nimport { GridFloor } from \"@/lib/components/ui/backgrounds/GridFloor\";\n\nexport default function App() {\n  return (\n    <div className=\"relative w-full h-screen\">\n\n      {/* Default synthwave floor */}\n      <GridFloor />\n\n      {/* Pink horizon */}\n      <GridFloor\n        lineColor=\"#ff00ff\"\n        glowColor=\"#ff00ff\"\n        bgColor=\"#0a020a\"\n        horizon={0.5}\n        speed={0.8}\n      />\n\n      {/* Static green wireframe */}\n      <GridFloor\n        lineColor=\"#39ff14\"\n        glowColor=\"#39ff14\"\n        bgColor=\"#000000\"\n        horizo\n```\n\nProps:\n  horizon [default: 0.45] - Horizon line as a fraction of container height (0–1).\n  columns [default: 24] - Number of vertical perspective lines.\n  rows [default: 18] - Number of horizontal grid rows receding into the distance.\n  lineColor - Color of the grid lines.\n  glowColor - Glow color applied as a drop-shadow to the lines.\n  bgColor - Background fill color behind the grid.\n  speed [default: 0.6] - Speed of the forward scrolling animation. Set to 0 to disable motion.\n  opacity [default: 0.85] - Maximum opacity of the grid lines (0–1).\n  lineWidth [default: 1] - Grid line width in pixels.\n  className [default: undefined] - Additional CSS classes for the canvas element.\n\n---\n## Grid Scene\nSlug: grid-scene\nDescription: Canvas-based perspective grid with both a floor and a mirrored ceiling meeting at a shared glowing horizon — classic synthwave room effect.\n\nUsage Example:\n```tsx\nimport { GridScene } from \"@/lib/components/ui/backgrounds/GridScene\";\n\nexport default function App() {\n  return (\n    <div className=\"relative w-full h-screen\">\n\n      {/* Default — cyan floor + ceiling */}\n      <GridScene />\n\n      {/* Pink synthwave scene */}\n      <GridScene\n        lineColor=\"#ff00ff\"\n        glowColor=\"#ff00ff\"\n        bgColor=\"#0a020a\"\n        horizon={0.5}\n        speed={0.8}\n      />\n\n      {/* Floor only */}\n      <GridScene\n        showCeiling={false}\n        horizon={0.45}\n      />\n\n      {/* Ceiling only */}\n     \n```\n\nProps:\n  horizon [default: 0.5] - Horizon line as a fraction of container height (0–1). 0.5 = vertical center.\n  gap [default: 0.08] - Empty space between floor and ceiling as a fraction of container height (0–1). Increase for a wider gap around the horizon.\n  columns [default: 24] - Number of vertical perspective lines on each plane.\n  rows [default: 18] - Number of horizontal grid rows receding into the distance per plane.\n  lineColor - Color of the grid lines.\n  glowColor - Glow color applied as a drop-shadow to the lines.\n  bgColor - Background fill color behind the grid.\n  speed [default: 0.6] - Speed of the forward scrolling animation. Set to 0 to disable motion.\n  opacity [default: 0.85] - Maximum opacity of the grid lines (0–1).\n  lineWidth [default: 1] - Grid line width in pixels.\n  showFloor [default: true] - Whether to render the floor grid (below the horizon).\n  showCeiling [default: true] - Whether to render the ceiling grid (mirrored above the horizon).\n  className [default: undefined] - Additional CSS classes for the canvas element.\n\n---\n## Hexagons\nSlug: hexagons\nDescription: Flat-top hexagon grid with customizable fill, border colors, hover highlight, ambient glow, and animated beam lines flowing along hex edges.\n\nUsage Example:\n```tsx\nimport { Hexagons } from \"@/lib/components/ui/backgrounds/Hexagons\";\r\n\r\nexport default function MyPage() {\r\n  return (\r\n    <div className=\"relative w-full h-screen bg-slate-950 overflow-hidden\">\r\n      {/* Hexagon Background */}\r\n      <Hexagons\r\n        hexColor=\"transparent\"              // cell fill (rgba or hex)\r\n        hexBorderColor=\"rgba(0,243,255,0.2)\"\r\n        hexSize={40}                        // circumradius in px\r\n        borderWidth={1}\r\n\r\n        hoverEffect={true}                  // hover is tracked at document level —\r\n     \n```\n\nProps:\n  hexColor - Fill color of each hexagon cell.\n  hexBorderColor - Stroke color for hexagon borders.\n  hexSize [default: 40] - Circumradius of each hexagon in pixels.\n  borderWidth [default: 1] - Stroke width of hexagon borders in pixels.\n  hoverEffect [default: true] - Enable hover effects. Controls both fill and border hover reactivity.\n  hoverColor - Fill color applied to the hovered hexagon. Set same as hexColor to disable fill change.\n  borderGlowEffect [default: false] - Enable a neon shadow glow rendered around every hex border. Color can differ from hexBorderColor.\n  borderGlowColor - Shadow/glow color for hex borders. Independent of the border stroke color.\n  borderGlowRadius [default: 10] - Blur radius (px) of the neon border glow.\n  beamEffect [default: false] - Enable animated beams that travel along hex edges from top to bottom.\n  beamColor - Color of the beam gradient body.\n  beamGlowColor - Shadow glow color of the bright beam head.\n  maxBeams [default: 20] - Maximum number of concurrent beams on screen.\n  beamSpeed [default: 2] - Base travel speed of beams in px per frame.\n  beamLength [default: 80] - Tail length of each beam in pixels.\n  beamSpawnProbability [default: 0.08] - Probability per frame of spawning a new beam (0–1).\n  overlay [default: false] - Add a radial-gradient dark vignette overlay on top of the grid.\n  className - Additional CSS class names for the root container.\n\n---\n## Holographic Terrain\nSlug: holographic-terrain\nDescription: Three.js wireframe terrain animated with layered sine waves and a cursor-reactive Gaussian bump. Mouse hover deforms the mesh in real time.\n\nUsage Example:\n```tsx\nimport { HolographicTerrain } from \"@/lib/components/ui/backgrounds/HolographicTerrain\";\\n\\nexport default function App() {\\n  return (\\n    <div className=\"relative w-screen h-screen\">\\n      <HolographicTerrain\\n        lineColor=\"#00ffff\"\\n        bgColor=\"#020a0a\"\\n        waveAmplitude={0.8}\\n        waveFrequency={1.5}\\n        bumpStrength={2.5}\\n      />\\n      {/* your content on top */}\\n    </div>\\n  );\\n}\n```\n\nProps:\n  lineColor - Wireframe line colour (hex).\n  bgColor - Renderer background colour and fog colour (hex).\n  waveAmplitude [default: 0.8] - Peak height of animated sine waves in world units.\n  waveFrequency [default: 1.5] - Spatial frequency of the terrain waves. Higher = more peaks.\n  waveSpeed [default: 1] - Animation speed multiplier.\n  bumpRadius [default: 3.5] - Radius of the cursor interaction bump in world units.\n  bumpStrength [default: 2.5] - Peak height of the Gaussian bump raised by cursor hover.\n  planeWidth [default: 24] - Terrain width along the X axis in world units.\n  planeDepth [default: 24] - Terrain depth/length along the Z axis in world units.\n  cameraHeight [default: 10] - Camera Y position above the terrain origin. Camera Z is auto-derived (height × 1.4) to maintain a ~35° viewing angle.\n  gridSegments [default: 60] - Subdivisions per axis of the terrain plane (higher = more detail, more GPU cost).\n  fog [default: true] - Exponential fog that fades terrain edges into bgColor.\n  opacity [default: 100] - Overall scene opacity (0–100).\n  className [default: undefined] - Extra class names applied to the wrapper div.\n\n---\n## NavBar\nSlug: navbar\nDescription: All-in-one navbar: standard or dock variant, submenus, profile menu, transparent/glass/solid, fixed/floating/sticky positioning.\n\nUsage Example:\n```tsx\nimport NavBar, { PRESET_PROFILE_ITEMS } from \"@/lib/components/ui/navbars/NavBar\";\\n\\nexport default function App() {\\n  return (\\n    <>\\n      {/* ── Standard navbar — fixed, glass, with submenu and profile ── */}\\n      <NavBar\\n        variant=\"standard\"\\n        position=\"fixed\"\\n        transparency=\"glass\"\\n        color=\"cyan\"\\n        logoText=\"NeonBlade\"\\n        items={[\\n          { label: \"Home\", href: \"/\" },\\n          {\\n            label: \"Products\",\\n            children: [\\n              { label: \"Component Library\", href: \"/c\n```\n\nProps:\n  color: \"cyan\" | \"pink\" | \"green\" | string - Accent color applied to hover states, submenu borders, profile avatar ring, and dock indicator. Preset name or any CSS color.\n  logo - Logo: an image URL string (rendered as <img>) or any ReactNode (e.g. a custom SVG).\n  logoText - Brand text displayed beside the logo.\n  logoHref - href the logo links to.\n  items [default: []] - Navigation links. Each item may include label, href, icon, onClick, and a children array for submenus.\n  showProfile [default: false] - Show a user avatar button that opens a profile dropdown.\n  profileAvatar - Avatar: an image URL or any ReactNode. Falls back to the first letter of profileName.\n  profileName - User display name shown at the top of the profile dropdown.\n  profileItems [default: PRESET_PROFILE_ITEMS] - Profile dropdown items. Each entry has key, label, icon, onClick, and divider. Use the exported PRESET_PROFILE_ITEMS or build your own.\n  onProfileAction - Callback fired when any profile menu item is clicked. Receives the item key.\n  scrollThreshold [default: 20] - Scroll distance in px before the scroll effect triggers.\n  dockPosition: \"top\" | \"bottom\" - Pin position for the dock variant.\n  dockShowLabels [default: true] - Show text labels beneath icons in the dock variant.\n  className - Extra CSS class names applied to the <nav> element.\n\n---\n## Neon Bar Chart\nSlug: neon-bar-chart\nDescription: Recharts-powered bar chart with top-rounded neon bars, custom glow drop-shadow, multi-color mode, multi-series support, and horizontal layout.\n\nUsage Example:\n```tsx\nimport NeonBarChart from \"@/components/neonblade-ui/neon-bar-chart\";\r\n\r\nconst data = [\r\n  { name: \"Mon\", visits: 1200 },\r\n  { name: \"Tue\", visits: 1900 },\r\n  { name: \"Wed\", visits: 1400 },\r\n  { name: \"Thu\", visits: 2300 },\r\n];\r\n\r\n// Vertical bars (default)\r\nexport default function App() {\r\n  return <NeonBarChart data={data} dataKey=\"visits\" color=\"cyan\" height={260} />;\r\n}\r\n\r\n// Multi-color single series\r\nexport function MultiColor() {\r\n  return <NeonBarChart data={data} dataKey=\"visits\" multiColor height={260} />;\r\n}\r\n\r\n// Horizontal layout\r\ne\n```\n\nProps:\n  data - Array of data objects keyed by xAxisKey + series dataKeys.\n  series - One or more bar series. Omit and use dataKey + color for a single series.\n  dataKey - Shorthand dataKey for a single series.\n  color: \"cyan\" | \"pink\" | \"green\" | string - Shorthand neon accent color for a single series.\n  label - Shorthand legend/tooltip label for a single series.\n  xAxisKey - Key in data used for category axis labels.\n  height [default: 260] - Chart height in px.\n  layout: \"vertical\" | \"horizontal\" - Bar orientation. Horizontal flips X/Y axes.\n  radius [default: 3] - Corner radius of each bar (top corners only, cyber style).\n  barGap [default: 0.35] - Gap between bars as a fraction of bar width (0–1).\n  grid [default: true] - Show a subtle neon grid behind the chart.\n  legend [default: false] - Show a series legend.\n  showYAxis [default: true] - Show Y-axis tick labels.\n  showXAxis [default: true] - Show X-axis tick labels.\n  glowIntensity: \"none\" | \"low\" | \"medium\" | \"high\" - Neon drop-shadow glow on each bar.\n  multiColor [default: false] - Auto-assign sequential neon colors to each bar in a single-series chart.\n  className - Additional className on the wrapper div.\n\n---\n## Neon Checkbox\nSlug: neon-checkbox\nDescription: Corner-cut cyberpunk checkbox with neon glow on check, animated SVG checkmark, indeterminate state (dash), size presets, and accessible aria-checked semantics.\n\nUsage Example:\n```tsx\nimport { useState } from \"react\";\nimport NeonCheckbox from \"@/components/neonblade-ui/neon-checkbox\";\n\n// Controlled\nexport default function App() {\n  const [agreed, setAgreed] = useState(false);\n  return (\n    <NeonCheckbox\n      label=\"Accept Terms of Service\"\n      checked={agreed}\n      onChange={setAgreed}\n      color=\"cyan\"\n    />\n  );\n}\n\n// Indeterminate\nexport function Partial() {\n  return <NeonCheckbox label=\"Select All\" indeterminate color=\"pink\" />;\n}\n```\n\nProps:\n  checked - Controlled checked state.\n  defaultChecked [default: false] - Default checked state (uncontrolled).\n  indeterminate [default: false] - Renders a dash instead of a checkmark (partial selection).\n  onChange - Change handler called with the new checked value.\n  color: \"cyan\" | \"pink\" | \"green\" | string - Neon accent color for the checked box.\n  size: \"sm\" | \"md\" | \"lg\" - Box size preset.\n  variant: \"square\" | \"corner-cut\" - Box style. square is a standard bordered box; corner-cut clips the bottom-right corner with a proper bordered diagonal.\n  disabled [default: false] - Disable the checkbox.\n  label - Label text displayed next to the box.\n  className - Additional className on the wrapper.\n  id - id for the input. Auto-generated if omitted.\n\n---\n## Neon Donut Chart\nSlug: neon-donut-chart\nDescription: Recharts-powered donut/ring chart with per-segment neon glow, interactive center label, hover dimming, auto color palette, and a custom legend.\n\nUsage Example:\n```tsx\nimport NeonDonutChart from \"@/components/neonblade-ui/neon-donut-chart\";\r\n\r\nconst data = [\r\n  { name: \"Direct\",  value: 4200 },\r\n  { name: \"Organic\", value: 3100 },\r\n  { name: \"Referral\",value: 1800 },\r\n  { name: \"Social\",  value: 920  },\r\n];\r\n\r\n// With center label + legend (default colors)\r\nexport default function App() {\r\n  return <NeonDonutChart data={data} centerLabel legend height={280} />;\r\n}\r\n\r\n// Named color per segment\r\nconst statusData = [\r\n  { name: \"Online\",  value: 87, color: \"green\" },\r\n  { name: \"Idle\",    value: 9,  color: \"cya\n```\n\nProps:\n  data - Array of segments. Each segment has name, value, and optional color.\n  height [default: 260] - Chart height in px.\n  innerRadius - Inner hole radius. Use percentage string (e.g. '60%') or absolute px number.\n  outerRadius - Outer ring radius. Use percentage string or absolute px number.\n  glowIntensity: \"none\" | \"low\" | \"medium\" | \"high\" - Neon glow spread on each segment.\n  paddingAngle [default: 2] - Gap between segments in degrees.\n  cornerRadius [default: 4] - Corner radius on each segment arc end in px.\n  centerLabel [default: true] - Show a center label with the hovered segment name + value (or total when nothing is hovered).\n  color: \"cyan\" | \"pink\" | \"green\" | string - Primary accent color — used for the total label and fallback tooltip.\n  legend [default: false] - Show a custom inline legend below the chart.\n  className - Additional className on the wrapper div.\n\n---\n## Neon Glow\nSlug: neon-glow\nDescription: Highly customizable neon glow text with single color, multi-color gradients (linear, radial, conic), and animated effects.\n\nUsage Example:\n```tsx\nimport NeonGlow from \"@/lib/components/ui/text/NeonGlow\";\r\n\r\nexport default function App() {\r\n  return (\r\n    <div className=\"flex flex-col gap-8\">\r\n      {/* Single color preset — glow auto-matches text color */}\r\n      <h2 className=\"text-4xl font-bold font-orbitron uppercase\">\r\n        <NeonGlow colors=\"cyan\">Neon Cyan</NeonGlow>\r\n      </h2>\r\n\r\n      {/* Single color — custom hex (any valid CSS color works) */}\r\n      <h2 className=\"text-4xl font-bold font-orbitron uppercase\">\r\n        <NeonGlow colors=\"#ff6600\" glowIntensity=\"strong\">Custo\n```\n\nProps:\n  children - The text content to display with the neon glow effect.\n  gradientDirection: \"left-right\" | \"right-left\" | \"top-bottom\" | \"bottom-top\" | \"diagonal-tl-br\" | \"diagonal-tr-bl\" | \"radial\" | \"conic\" - Direction of the gradient. Only relevant when colors contains more than one entry.\n  glowIntensity: \"none\" | \"subtle\" | \"normal\" | \"strong\" | \"intense\" - Intensity of the neon glow. Drives text-shadow for single-color text and filter: drop-shadow() for gradient text.\n  glowColor: \"cyan\" | \"pink\" | \"green\" | \"purple\" | \"orange\" | \"yellow\" | string - Pin the glow to a specific color (preset name or any CSS color). For single-color text this defaults to the text color. For gradient text no glow is applied unless glowColor or gradientGlow is set.\n  gradientGlow [default: false] - When true and colors is multi-color, applies layered drop-shadow filters using each gradient color, producing a multi-hued halo that mirrors the text gradient. Takes precedence over glowColor for gradient text.\n  className - Additional Tailwind or custom CSS classes — use this for font size, weight, family, spacing, etc.\n\n---\n## Neon Glow Corner Cut Card\nSlug: neon-glow-corner-cut-card\nDescription: A corner cut card with a neon gradient glow backdrop, icon box, and fully customizable colors, sizes and hover effects.\n\nUsage Example:\n```tsx\nimport NeonGlowCornerCutCard from \"@/lib/components/ui/cards/NeonGlowCornerCutCard\";\\nimport { Terminal, Zap } from \"lucide-react\";\\n\\nexport default function App() {\\n  return (\\n    <div className=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\\n      <NeonGlowCornerCutCard\\n        title=\"CLI Installation\"\\n        description=\"Install components directly into your project via CLI.\"\\n        colorA=\"cyan\"\\n        colorB=\"pink\"\\n        hoverEffect=\"gradient\"\\n        icon={<Terminal className=\"w-full h-full\" />}\\n      />\\n\\n      {/* Solid hover,\n```\n\nProps:\n  children - Free-form slot rendered below title/description. Use alone for a fully custom card body.\n  icon - Element rendered inside the top icon box (e.g. a Lucide icon).\n  title - Card heading text.\n  description - Body copy rendered below the title.\n  colorA: \"cyan\" | \"pink\" | \"green\" | string - Gradient start color and icon/title glow color. Accept preset names or any CSS color.\n  size: \"sm\" | \"md\" | \"lg\" | \"xl\" - Controls inner card padding, icon box, and font sizes.\n  corner: \"bottom-right\" | \"bottom-left\" | \"top-right\" | \"top-left\" | \"all\" - Which corner(s) receive the diagonal cut.\n  cornerSize [default: 20] - Depth of the diagonal corner cut in pixels.\n  glowIntensity: \"low\" | \"medium\" | \"high\" - Spread radius of the neon glow effects.\n  bgColor - Override the inner card background color (default: #0a0a0a).\n\n---\n## Neon Input\nSlug: neon-input\nDescription: A fully-featured text input with the iconic NeonBlade corner-cut shape, neon focus glow, full color customization, label, hint, error state, prefix/suffix slots, border styles, background opacity, and all standard HTML input types.\n\nUsage Example:\n```tsx\nimport NeonInput from \"@/lib/components/ui/inputs/NeonInput\";\r\n\r\n// ── Minimal — default corner-cut, cyan ─────────────────────────────────────\r\nexport function MinimalExample() {\r\n  return (\r\n    <NeonInput\r\n      placeholder=\"Enter username\"\r\n      label=\"Username\"\r\n    />\r\n  );\r\n}\r\n\r\n// ── Password field ─────────────────────────────────────────────────────────\r\nexport function PasswordExample() {\r\n  return (\r\n    <NeonInput\r\n      type=\"password\"\r\n      label=\"Password\"\r\n      placeholder=\"••••••••\"\r\n      color=\"pink\"\r\n      hint=\"At least\n```\n\nProps:\n  cornerSize [default: 12] - Depth of the diagonal corner cut in pixels. Only applies when shape is corner-cut.\n  color: \"cyan\" | \"pink\" | \"green\" | \"orange\" | \"purple\" | \"red\" | string - Main accent color — drives the border, focus glow, caret, and prefix/suffix icon tint. Accepts a preset name or any CSS color value.\n  borderColor [default: —] - Override the default border color. Falls back to `color` when not set.\n  hoverColor [default: —] - Border color on hover. Falls back to `color` when not set.\n  focusColor [default: —] - Border and glow color when the input is focused. Falls back to `color` when not set.\n  bgColor - Background color of the input field.\n  textColor - Color of the typed value text.\n  placeholderColor [default: —] - Color of the placeholder text. Defaults to the accent color at 35% opacity.\n  label [default: —] - Optional label rendered above the input in font-orbitron uppercase.\n  labelColor [default: —] - Color of the label. Defaults to the accent color at 65% opacity.\n  hint [default: —] - Helper text shown below the input in a muted color.\n  hintColor [default: —] - Color of the hint text.\n  error [default: —] - Error message. When set the border turns red and this message is shown below the input instead of hint.\n  size: \"sm\" | \"md\" | \"lg\" - Controls padding, height, and font size of the input.\n  glowIntensity: \"none\" | \"subtle\" | \"normal\" | \"strong\" - Spread of the neon drop-shadow emitted when the input is focused.\n  prefix [default: —] - Node rendered before the input text — ideal for icons or short strings.\n  suffix [default: —] - Node rendered after the input text — ideal for icons, action buttons, or unit labels.\n  type: \"text\" | \"password\" | \"email\" | \"number\" | \"search\" | \"tel\" | \"url\" | string - Native HTML input type. All standard values are supported — passwords render as dots, number shows spinners, etc.\n  disabled [default: false] - Disables the input and reduces opacity.\n  className [default: —] - Extra class names applied to the outermost wrapper div.\n  inputClassName [default: —] - Extra class names applied directly to the native <input> element.\n\n---\n## Neon Line Chart\nSlug: neon-line-chart\nDescription: Recharts-powered line/area chart with neon glow strokes, gradient area fills, multi-series support, and a corner-cut tooltip.\n\nUsage Example:\n```tsx\nimport NeonLineChart from \"@/components/neonblade-ui/neon-line-chart\";\r\n\r\nconst data = [\r\n  { name: \"Mon\", value: 820 },\r\n  { name: \"Tue\", value: 1340 },\r\n  { name: \"Wed\", value: 980 },\r\n  { name: \"Thu\", value: 1620 },\r\n  { name: \"Fri\", value: 1190 },\r\n  { name: \"Sat\", value: 2040 },\r\n  { name: \"Sun\", value: 1760 },\r\n];\r\n\r\n// Single series\r\nexport default function App() {\r\n  return <NeonLineChart data={data} dataKey=\"value\" color=\"cyan\" height={260} />;\r\n}\r\n\r\n// Multi-series\r\nconst multiData = [\r\n  { name: \"Jan\", requests: 4200, errors: 140 },\r\n```\n\nProps:\n  data - Array of data objects keyed by xAxisKey + series dataKeys.\n  series - One or more line series. Omit and use dataKey + color for a single series.\n  dataKey - Shorthand dataKey when using a single series.\n  color: \"cyan\" | \"pink\" | \"green\" | string - Shorthand neon accent color for a single series.\n  label - Shorthand legend/tooltip label for a single series.\n  xAxisKey - Key in data used for X axis labels.\n  height [default: 260] - Chart height in px.\n  area [default: true] - Show a gradient-filled area under each line.\n  dots [default: false] - Render dot markers on each data point.\n  grid [default: true] - Show a subtle neon grid behind the chart.\n  legend [default: false] - Show a series legend below the chart.\n  strokeWidth [default: 2] - Line stroke width in px.\n  glowIntensity: \"none\" | \"low\" | \"medium\" | \"high\" - Neon drop-shadow glow on the line stroke.\n  curve: \"monotone\" | \"linear\" | \"step\" | \"stepAfter\" | \"stepBefore\" | \"basis\" - Recharts curve interpolation type.\n  showYAxis [default: true] - Show Y-axis tick labels.\n  showXAxis [default: true] - Show X-axis tick labels.\n  className - Additional className on the wrapper div.\n\n---\n## Neon Select\nSlug: neon-select\nDescription: Fully accessible custom dropdown with keyboard navigation (arrows/enter/esc), controlled and uncontrolled modes, neon glow trigger, animated clip-path listbox panel, and disabled option support.\n\nUsage Example:\n```tsx\nimport { useState } from \"react\";\nimport NeonSelect from \"@/components/neonblade-ui/neon-select\";\n\nconst options = [\n  { value: \"engineer\", label: \"Engineer\" },\n  { value: \"analyst\",  label: \"Analyst\"  },\n  { value: \"designer\", label: \"Designer\" },\n];\n\n// Controlled\nexport default function App() {\n  const [role, setRole] = useState(\"\");\n  return (\n    <NeonSelect\n      options={options}\n      value={role}\n      onChange={setRole}\n      placeholder=\"SELECT ROLE...\"\n      color=\"cyan\"\n    />\n  );\n}\n\n// Uncontrolled with default\nexport function Pr\n```\n\nProps:\n  value - Controlled selected value.\n  defaultValue - Default value (uncontrolled).\n  onChange - Change handler called with the selected option value.\n  placeholder - Placeholder text when nothing is selected.\n  color: \"cyan\" | \"pink\" | \"green\" | string - Neon accent color.\n  size: \"sm\" | \"md\" | \"lg\" - Size preset controlling padding and font size.\n  variant: \"square\" | \"corner-cut\" - square is a standard bordered box; corner-cut clips the bottom-right corner with a properly bordered diagonal using the two-layer frame technique.\n  label - Optional field label rendered above the trigger in accent colour.\n  disabled [default: false] - Disable the entire select.\n  className - Additional className on the wrapper.\n  id - id for the trigger button.\n  ariaLabel - aria-label for the trigger and dropdown list.\n\n---\n## Neon Sparkline\nSlug: neon-sparkline\nDescription: Inline mini sparkline for embedding in KPI cards and stat widgets. Neon glow stroke, gradient fill, and a minimal tooltip.\n\nUsage Example:\n```tsx\nimport NeonSparkline from \"@/components/neonblade-ui/neon-sparkline\";\r\n\r\nconst data = [\r\n  { value: 10 }, { value: 14 }, { value: 11 }, { value: 18 },\r\n  { value: 20 }, { value: 17 }, { value: 25 }, { value: 30 },\r\n];\r\n\r\n// Basic inline sparkline\r\nexport default function App() {\r\n  return <NeonSparkline data={data} color=\"cyan\" width={120} height={40} />;\r\n}\r\n\r\n// Embedded in a KPI card\r\nexport function KPICard() {\r\n  return (\r\n    <div className=\"border border-white/10 bg-black/50 px-4 pt-4 pb-0 rounded-sm\">\r\n      <p className=\"text-xs text-w\n```\n\nProps:\n  data - Array of data points. Each must have a value number (or use dataKey).\n  dataKey - Key to read from each data point.\n  color: \"cyan\" | \"pink\" | \"green\" | string - Neon color preset or any CSS hex color.\n  width [default: 120] - Width of the sparkline in px (or '100%' for responsive).\n  height [default: 40] - Height of the sparkline in px.\n  strokeWidth [default: 1.5] - Line stroke width in px.\n  glowIntensity: \"none\" | \"low\" | \"medium\" | \"high\" - Neon drop-shadow glow intensity on the line.\n  area [default: true] - Show a gradient-filled area under the line.\n  curve: \"monotone\" | \"linear\" | \"step\" - Line interpolation type.\n  tooltip [default: true] - Show a minimal cyberpunk tooltip on hover.\n  className - Additional className on the outer wrapper span.\n\n---\n## Neon Table\nSlug: neon-table\nDescription: Sortable, paginated data table with neon scan-line row hover, corner accent marks, animated sort indicators, custom cell renderers, striped rows, and cyberpunk pagination controls.\n\nUsage Example:\n```tsx\nimport NeonTable, { NTColumn } from \"@/components/neonblade-ui/neon-table\";\n\ntype Row = { id: number; name: string; role: string; score: number };\n\nconst data: Row[] = [\n  { id: 1, name: \"Kira Nakamura\", role: \"Engineer\", score: 9420 },\n  { id: 2, name: \"Zane Holloway\", role: \"Analyst\",  score: 7810 },\n  { id: 3, name: \"Lyra Chen\",     role: \"Designer\", score: 6540 },\n];\n\nconst columns: NTColumn<Row>[] = [\n  { key: \"id\",    header: \"#\",     width: \"48px\", align: \"center\" },\n  { key: \"name\",  header: \"Agent\", sortable: true },\n  { key: \"role\",  \n```\n\nProps:\n  data - Array of row data objects. Each key maps to a column.\n  columns - Column definitions — key, header, render?, sortable?, width?, align?.\n  title - Optional title shown in a header bar with a pulsing dot and accent line.\n  color: \"cyan\" | \"pink\" | \"green\" | string - Neon accent color for header, hover beam, and pagination.\n  rowHover [default: true] - Enable neon scan-line left-border on row hover.\n  sortable [default: true] - Enable client-side column sorting.\n  pageSize [default: 0] - Rows per page. 0 disables pagination.\n  emptyText - Message shown when data is empty.\n  grid [default: true] - Show subtle vertical dividers between columns.\n  striped [default: false] - Alternate row background shading.\n  compact [default: false] - Tighter row and cell padding for dense data.\n  loading [default: false] - Show animated skeleton rows instead of data.\n  loadingRows [default: 5] - Number of skeleton rows to display while loading.\n  corners [default: true] - Show neon accent corner marks on the table border.\n  className - Additional className on the outer wrapper.\n\n---\n## Neon Tide\nSlug: neon-tide\nDescription: Cinematic 3D wave surface flowing diagonally between screen corners with real depth. Single or dual-color gradients, glow/gloss lighting, and cursor-reactive ripples.\n\nUsage Example:\n```tsx\nimport { NeonTide } from \"@/lib/components/ui/backgrounds/NeonTide\";\\n\\nexport default function App() {\\n  return (\\n    <div className=\"relative w-screen h-screen\">\\n      <NeonTide\\n        colorA=\"#00f3ff\"\\n        colorB=\"#ff00e6\"\\n        origin=\"top-right\"\\n        speed={0.5}\\n        amplitude={1.1}\\n      />\\n      {/* your content on top */}\\n    </div>\\n  );\\n}\n```\n\nProps:\n  colorA - Primary wave colour (hex).\n  colorB [default: undefined] - Secondary wave colour used to gradient crests vs. troughs. Omit for a single-colour look (defaults to colorA).\n  bgColor - Renderer background colour and fog colour (hex).\n  origin: \"top-left\" | \"top-right\" | \"bottom-left\" | \"bottom-right\" - Corner the waves flow from. They always travel toward the opposite corner (e.g. top-right → bottom-left), receding in 3D depth rather than a flat 2D diagonal.\n  speed [default: 0.5] - Animation speed multiplier for the wave flow.\n  amplitude [default: 1.2] - Wave height in world units.\n  frequency [default: 0.55] - Spatial frequency/density of the waves. Higher = more ripples.\n  glow [default: 0.9] - Fresnel rim-light glow intensity along wave edges.\n  gloss [default: 0.6] - Specular highlight intensity on wave crests.\n  planeWidth [default: 34] - Surface width along the X axis in world units.\n  planeDepth [default: 34] - Surface depth along the Z axis in world units — how far the waves recede into the screen.\n  cameraHeight [default: 11] - Camera Y position above the surface origin.\n  cameraTilt [default: 1.6] - Camera distance multiplier relative to cameraHeight. Higher values flatten the angle for a more cinematic, distant look.\n  gridSegments [default: 120] - Subdivisions per axis of the wave surface (higher = smoother, more GPU cost).\n  fog [default: true] - Exponential fog that fades the surface edges into bgColor.\n  opacity [default: 100] - Overall scene opacity (0–100).\n  hoverEffect [default: true] - Enables a cursor-reactive ripple and highlight on the wave surface.\n  hoverRadius [default: 4] - Radius of the cursor ripple in world units.\n  hoverStrength [default: 1.4] - Peak height added by the cursor ripple.\n  className [default: undefined] - Extra class names applied to the wrapper div.\n\n---\n## Neon Toggle\nSlug: neon-toggle\nDescription: An accessible switch/toggle with a neon-glowing track, animated thumb slide, spark particle burst on activation, size presets, and full color control. Supports controlled and uncontrolled modes.\n\nUsage Example:\n```tsx\nimport { useState } from \"react\";\nimport NeonToggle from \"@/components/neonblade-ui/neon-toggle\";\n\n// Controlled\nexport default function App() {\n  const [on, setOn] = useState(false);\n  return (\n    <NeonToggle\n      label=\"Enable Auto-Scan\"\n      checked={on}\n      onChange={setOn}\n      color=\"cyan\"\n    />\n  );\n}\n\n// Uncontrolled\nexport function Uncontrolled() {\n  return <NeonToggle label=\"Dark Mode\" defaultChecked color=\"pink\" size=\"lg\" />;\n}\n```\n\nProps:\n  checked - Controlled checked state.\n  defaultChecked [default: false] - Default checked state (uncontrolled).\n  onChange - Change handler called with the new checked value.\n  color: \"cyan\" | \"pink\" | \"green\" | string - Neon accent color for the ON state.\n  size: \"sm\" | \"md\" | \"lg\" - Track size preset.\n  disabled [default: false] - Disable the toggle.\n  label - Label text displayed next to the toggle.\n  labelPosition: \"left\" | \"right\" - Label position relative to the toggle.\n  className - Additional className on the label wrapper.\n  id - id for the underlying input. Auto-generated if omitted.\n\n---\n## Notch Card\nSlug: notch-card\nDescription: Futuristic card with rectangular notch indentations on any sides, beam border, gradient border, and hover effects.\n\nUsage Example:\n```tsx\nimport { NotchCard } from \"@/lib/components/ui/cards/NotchCard\";\\nimport { Cpu, Zap, Shield } from \"lucide-react\";\\n\\nexport default function App() {\\n  return (\\n    <div className=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\\n      {/* Default: top + bottom notches, cyan border */}\\n      <NotchCard\\n        title=\"Cyber Unit\"\\n        description=\"Default top & bottom notches with cyan accent.\"\\n        icon={<Cpu className=\"w-full h-full\" />}\\n      />\\n\\n      {/* Gradient border + pink accent + beam */}\\n      <NotchCard\\n        borderGradie\n```\n\nProps:\n  children - Free-form slot rendered below the optional title/description.\n  icon - Element rendered inside the top icon box (e.g. a Lucide icon).\n  title - Card heading text.\n  description - Body copy rendered below the title.\n  notchSides: (\"top\" | \"bottom\" | \"left\" | \"right\")[] [default: [] - Sides that receive notch indentations. At least one side must be provided.\n  notchSize [default: 12] - Depth of each notch indentation in pixels.\n  notchWidth [default: 50] - Width of the flat notch floor on top & bottom edges in pixels.\n  notchWidthV [default: notchWidth] - Width of the flat notch floor on left & right edges in pixels. Falls back to notchWidth when omitted.\n  notchSkew [default: 12] - Horizontal run of the angled entry/exit walls in pixels. Larger = shallower / more gradual angle.\n  borderWidth - Border thickness — becomes the padding between outer and inner card.\n  borderColor: \"cyan\" | \"pink\" | \"green\" | string - Primary border color. Preset name or any CSS color.\n  borderColorB: \"cyan\" | \"pink\" | \"green\" | string - Secondary border color used when borderGradient is true.\n  borderGradient [default: false] - Use a linear gradient as the static border instead of a solid color.\n  beamColor: \"cyan\" | \"pink\" | \"green\" | string - Primary beam color.\n  beamDuration [default: 4] - Primary beam rotation speed in seconds.\n  beamDurationB [default: 6] - Secondary beam rotation speed in seconds (dual variant only).\n  cardColor - Override the inner card background color (default: var(--background)).\n  textColor - Text color applied to the inner content wrapper.\n  accentColor: \"cyan\" | \"pink\" | \"green\" | string - Accent color for glow and hover highlights. Defaults to borderColor.\n  glowIntensity: \"none\" | \"low\" | \"medium\" | \"high\" - Ambient neon glow spread on the inner card surface.\n  align: \"start\" | \"center\" - Horizontal alignment of card content (icon, title, description, children).\n  size: \"sm\" | \"md\" | \"lg\" | \"xl\" - Controls inner padding and font sizes.\n  innerClassName - Extra className applied to the inner content div.\n\n---\n## Outline Text\nSlug: outline-text\nDescription: Outline-only text with customizable stroke color, fill, stroke width, per-letter proximity hover effect, color transitions, and neon glow.\n\nUsage Example:\n```tsx\nimport OutlineText from \"@/lib/components/ui/text/OutlineText\";\r\n\r\nexport default function App() {\r\n  return (\r\n    <div className=\"flex flex-col gap-10\">\r\n      {/* Pure outline — transparent fill, cyan stroke */}\r\n      <h2 className=\"font-black font-orbitron uppercase\">\r\n        <OutlineText strokeColor=\"cyan\" fontSize=\"3rem\">\r\n          OUTLINE\r\n        </OutlineText>\r\n      </h2>\r\n\r\n      {/* Solid dark fill + stroke */}\r\n      <h2 className=\"font-black font-orbitron uppercase\">\r\n        <OutlineText\r\n          strokeColor=\"pink\"\r\n        \n```\n\nProps:\n  children - The text string to render as outlined letters. Each character is wrapped individually to support per-letter proximity activation.\n  strokeColor: \"cyan\" | \"pink\" | \"green\" | \"purple\" | \"orange\" | \"yellow\" | string - Color of the letter outline/stroke in the default (non-hovered) state. Accepts preset names or any valid CSS color string — hex, rgb, hsl, etc.\n  strokeWidth [default: 1] - Thickness of the letter outline stroke in pixels.\n  hoverStrokeColor: \"cyan\" | \"pink\" | \"green\" | \"purple\" | \"orange\" | \"yellow\" | string - Stroke color in the hover / proximity-activated state. Defaults to strokeColor when not provided.\n  hoverFillColor - Fill color of the inner part of the letters in the hover / proximity-activated state. Defaults to fillColor.\n  hoverGlowIntensity: \"none\" | \"subtle\" | \"normal\" | \"strong\" | \"intense\" - Intensity of the neon text-shadow glow applied to each letter when it is hover / proximity-activated.\n  hoverGlowColor: \"cyan\" | \"pink\" | \"green\" | \"purple\" | \"orange\" | \"yellow\" | string - Color of the glow effect on hover / proximity activation. Defaults to hoverStrokeColor, which in turn defaults to strokeColor.\n  proximityRadius [default: 100] - Radius in pixels within which a letter transitions to its hover state individually as the cursor draws near. Increase for a wider activation zone.\n  proximityEffect [default: true] - Enable the per-letter proximity effect driven by cursor distance. When false, hovering anywhere over the text activates all letters at once (whole-text hover).\n  transitionDuration [default: 200] - Duration in milliseconds for the stroke color, fill color, and glow transitions on each letter.\n  className - Additional Tailwind or custom CSS classes applied to the outer wrapper. Use this for font weight, font family, letter spacing, line height, etc.\n\n---\n## Pluviophile\nSlug: pluviophile\nDescription: Natural rain background with canvas-rendered falling streaks. Configurable angle, speed, color, density, and drop size.\n\nUsage Example:\n```tsx\nimport Pluviophile from \"@/lib/components/ui/backgrounds/Pluviophile\";\r\n\r\nexport default function App() {\r\n  return (\r\n    <div className=\"relative w-full h-screen\">\r\n\r\n      {/* Default rain */}\r\n      <Pluviophile />\r\n\r\n      {/* Straight falling, slow drizzle */}\r\n      <Pluviophile\r\n        angle={0}\r\n        speed={5}\r\n        dropCount={80}\r\n        dropMinLength={10}\r\n        dropMaxLength={22}\r\n        opacity={0.55}\r\n      />\r\n\r\n      {/* Heavy downpour */}\r\n      <Pluviophile\r\n        dropCount={280}\r\n        speed={18}\r\n        dropM\n```\n\nProps:\n  dropColor - Color of the falling rain streaks. Accepts any valid CSS color string — hex, rgb, rgba, hsl.\n  dropCount [default: 150] - Number of simultaneous falling rain streaks. Higher values produce heavier rainfall.\n  speed [default: 12] - Fall speed in pixels per frame. Each drop has ±25% speed variation for a natural look.\n  angle [default: -15] - Angle of rainfall in degrees from vertical. Negative values lean left (wind from right); positive values lean right. Clamped to ±60°.\n  dropMinLength [default: 15] - Minimum length of a falling rain streak in pixels.\n  dropMaxLength [default: 40] - Maximum length of a falling rain streak in pixels.\n  dropWidth [default: 1] - Stroke width of each falling rain streak in pixels. Each drop has slight width variation.\n  opacity [default: 0.75] - Global opacity of the entire rain canvas layer (0–1).\n  backgroundColor - Background fill color of the component. The canvas redraws this every frame as the base layer beneath the rain.\n\n---\n## Progress Bar\nSlug: progress-bar\nDescription: Horizontal neon progress bar with solid, segmented, striped, and pulse variants. Supports size presets, glow, percentage label, and smooth fill transition.\n\nUsage Example:\n```tsx\nimport ProgressBar from \"@/components/neonblade-ui/progress-bar\";\n\n// Solid bar with label\nexport default function App() {\n  return <ProgressBar value={73} color=\"cyan\" size=\"md\" showLabel glow />;\n}\n\n// Segmented variant (pink)\nexport function Segmented() {\n  return <ProgressBar value={60} color=\"pink\" size=\"lg\" variant=\"segmented\" showLabel glow />;\n}\n\n// Pulse variant\nexport function Pulse() {\n  return <ProgressBar value={30} color=\"green\" size=\"md\" variant=\"pulse\" />;\n}\n```\n\nProps:\n  value - Current fill value (0 to max).\n  max [default: 100] - Maximum value.\n  color: \"cyan\" | \"pink\" | \"green\" | string - Neon accent color.\n  variant: \"solid\" | \"segmented\" | \"striped\" | \"pulse\" - Visual style of the filled bar. For an indeterminate arrow loader, use the ArrowLoader component.\n  size: \"xs\" | \"sm\" | \"md\" | \"lg\" - Bar height preset.\n  showLabel [default: false] - Show a percentage label above the bar.\n  label - Custom label text (overrides the auto %).\n  glow [default: true] - Neon glow on the filled bar.\n  className - Additional className on the wrapper.\n\n---\n## Rain Loader\nSlug: rain-loader\nDescription: Four bars drop in one by one with staggered delay, hold together at the base, then fall away in sequence — a smooth, satisfying loop. Ideal for card, image, and section skeleton loaders.\n\nUsage Example:\n```tsx\nimport { RainLoader } from \"@/lib/components/ui/progress/RainLoader\";\n\nexport default function App() {\n  return (\n    <>\n      {/* Drop-in anywhere — works great as an inline card loader */}\n      <RainLoader />\n\n      {/* Custom color and size */}\n      <RainLoader color=\"pink\" size=\"lg\" />\n\n      {/* Slow, relaxed loop for ambient UI */}\n      <RainLoader color=\"green\" size=\"xl\" duration={2800} glowIntensity=\"high\" />\n\n      {/* Compact inline use — e.g. inside an image card */}\n      <RainLoader color=\"cyan\" size=\"sm\" barCount={3} duration={\n```\n\nProps:\n  size: \"xs\" | \"sm\" | \"md\" | \"lg\" | \"xl\" | number - Height of each bar in pixels, or a size preset. xs=24, sm=36, md=52, lg=72, xl=96. Pass a number for exact pixel control.\n  duration [default: 1600] - Full animation cycle duration in milliseconds. Lower values = faster rain, higher values = slower and more relaxed.\n  barCount [default: 4] - Number of bars (clamped to 2–8). Stagger delay adjusts automatically.\n  barWidthRatio [default: 0.115] - Bar width as a fraction of the bar height (e.g. 0.1 = 10% of height). Controls how thick or thin the bars appear.\n  gap [default: auto] - Pixel gap between bars. Defaults to ~70% of bar width if not specified.\n  borderRadius [default: auto] - Corner radius of each bar in pixels. Defaults to ~35% of bar width for a slightly rounded look.\n  glowIntensity: \"none\" | \"low\" | \"medium\" | \"high\" - Neon drop-shadow glow around the bars. Set to none to disable.\n  className - Extra class names applied to the outer wrapper div.\n\n---\n## Stat Card\nSlug: stat-card\nDescription: Dashboard KPI metric card with neon corner accents, scan-line hover, large value display, trend arrow with color coding, and an embedded NeonSparkline.\n\nUsage Example:\n```tsx\nimport StatCard from \"@/components/neonblade-ui/stat-card\";\r\nimport { Activity, DollarSign } from \"lucide-react\";\r\n\r\nconst spark = [\r\n  { value: 28 }, { value: 35 }, { value: 30 },\r\n  { value: 42 }, { value: 38 }, { value: 50 },\r\n];\r\n\r\n// Full KPI card with sparkline\r\nexport default function App() {\r\n  return (\r\n    <StatCard\r\n      label=\"Total Revenue\"\r\n      value=\"$48,290\"\r\n      trend=\"up\"\r\n      change=\"+12.4%\"\r\n      changeLabel=\"vs last month\"\r\n      color=\"cyan\"\r\n      sparkData={spark}\r\n      icon={<DollarSign size={16} />}\r\n    />\r\n \n```\n\nProps:\n  value - Primary metric value displayed in large text.\n  label - Short label describing the metric (shown above the value).\n  unit - Unit or suffix appended after the value (e.g. '%', 'ms', 'GB').\n  trend: \"up\" | \"down\" | \"neutral\" - Trend direction. Renders a colored arrow: green ▲ for up, pink ▼ for down, grey — for neutral.\n  change - Trend change text shown alongside the arrow (e.g. '+12.4%', '-6ms').\n  changeLabel - Secondary label next to the change text (e.g. 'vs last week').\n  sparkData - Optional sparkline data array. When provided, a NeonSparkline is rendered flush to the card bottom.\n  color: \"cyan\" | \"pink\" | \"green\" | string - Neon accent color — applied to border glow, corner accents, value glow, and sparkline.\n  icon - Icon element displayed in the top-right corner (e.g. a Lucide icon).\n  background - Background color of the card.\n  glowIntensity: \"none\" | \"low\" | \"medium\" | \"high\" - Neon glow intensity of the border shadow and corner accents.\n  className - Additional className on the outer card div.\n\n---\n## Timeline\nSlug: timeline\nDescription: Futuristic neon timeline with multiple variants, dot shapes, line styles, alignment modes, and staggered animate-in.\n\nUsage Example:\n```tsx\nimport Timeline from \"@/lib/components/ui/elements/Timeline\";\\n\\nconst items = [\\n  {\\n    date: \"Jan 2024\",\\n    title: \"Project Kickoff\",\\n    description: \"Repository created, toolchain configured, and initial component scaffolding complete.\",\\n    badge: \"v0.1\",\\n  },\\n  {\\n    date: \"Mar 2024\",\\n    title: \"Core Components\",\\n    description: \"Cards, buttons, badges, and frame components shipped with full prop APIs.\",\\n    badge: \"v0.5\",\\n    active: true,\\n  },\\n  {\\n    date: \"Jun 2024\",\\n    title: \"CLI Tool Released\",\\n    description:\n```\n\nProps:\n  items - Array of timeline items to render. Each item has: title (required), date, description, badge, icon, active.\n  color: \"cyan\" | \"pink\" | \"green\" | string - Accent color. Use a preset name or any CSS color value.\n  lineStyle: \"solid\" | \"dashed\" | \"glow\" | \"none\" - Style of the vertical connector line.\n  dotStyle: \"circle\" | \"square\" | \"diamond\" - Shape of the connector node dot.\n  animate [default: false] - When true, items animate in with a staggered fade-slide effect on mount.\n  className - Extra CSS class names applied to the root element.\n\n---\n## Turbine Loader\nSlug: turbine-loader\nDescription: A mechanical turbine-style spinner with one or more concentric rings, counter-rotating blades, and full control over color, size, blade count, speed, glow, and proportions.\n\nUsage Example:\n```tsx\nimport TurbineLoader from \"@/components/neonblade-ui/turbine-loader\";\n\nexport default function App() {\n  return (\n    <>\n      {/* Default twin-ring turbine */}\n      <TurbineLoader />\n\n      {/* Large high-glow boot indicator */}\n      <TurbineLoader\n        color=\"#00f3ff\"\n        size=\"xl\"\n        ringCount={3}\n        bladeCount={10}\n        speed={2400}\n        glowIntensity=\"high\"\n      />\n\n      {/* Compact inline spinner */}\n      <TurbineLoader color=\"pink\" size=\"sm\" bladeCount={6} speed={900} />\n\n      {/* Custom proportions */}\n     \n```\n\nProps:\n  color: \"cyan\" | \"pink\" | \"green\" | \"white\" | \"orange\" | string - Neon accent color for the blades, hub, and glow. Use a preset name or any valid CSS color value.\n  size: \"xs\" | \"sm\" | \"md\" | \"lg\" | \"xl\" | number - Overall width/height in pixels, or a size preset. xs=32, sm=48, md=72, lg=96, xl=128.\n  ringCount [default: 2] - Number of concentric turbine rings (clamped to 1–4). Inner rings rotate in the opposite direction.\n  bladeCount [default: 8] - Number of blades per ring (clamped to 3–16).\n  speed [default: 1800] - Full rotation duration in milliseconds. Lower = faster spin.\n  direction: \"clockwise\" | \"counter-clockwise\" - Rotation direction of the outer ring. Each inner ring automatically alternates direction for a mechanical turbine effect.\n  glowIntensity: \"none\" | \"low\" | \"medium\" | \"high\" - Neon drop-shadow glow around the whole turbine.\n  hubSize [default: 0.16] - Central hub radius as a fraction of the outer turbine radius (0–1).\n  bladeWidth [default: 0.5] - Blade base width as a fraction of the ring thickness (0–1).\n  bladeTaper [default: 0.35] - Blade tip width as a fraction of the blade base width (0–1).\n  ringGap [default: 0.06] - Gap between concentric rings as a fraction of the outer turbine radius.\n  className - Extra class names applied to the outer wrapper div.\n\n";
